{"ORD_FRISK_FAR","reg=outlaw,raider,gang,club,crime,prison",{"Come on over, I'm ticklish though","Come on over, I don't bite, much"}},
{"ORD_FRISK_FAR","reg=outlaw,club,crime",{"You want to search me, come and do it","Come here, then - slowly"}},
